INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) VALUES ('f17f8dc1-e43b-4dd3-a220-000000000001','quote','Ngày 7-4-1926 — Thánh Ngôn Hiệp Tuyển','Nhiên Đăng Cổ Phật thị ngã, Thích Ca Mâu Ni thị ngã, Thái Thượng Ngươn Thỉ thị ngã, Kim viết Cao Đài.','Đức Chí Tôn','https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-7-4-1926','Thánh Ngôn Hiệp Tuyển — Quyển 1, bản điện tử ghi nguồn ấn bản 1928, bài ngày 7-4-1926','Vĩnh Nguyên Tự, 7 Avril 1926','Đã đối chiếu với trang điện tử riêng; cần kiểm tra bản in, văn cảnh và quyền sử dụng.','excerpt:https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-7-4-1926');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) VALUES ('f17f8dc1-e43b-4dd3-a220-000000000002','quote','Ngày 8-4-1926 — Thánh Ngôn Hiệp Tuyển','Chúng sanh là toàn cả nhơn loại, chớ không phải là lựa chọn một phần người, như ý phàm các con tính rỗi.','Đức Chí Tôn','https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-8-4-1926','Thánh Ngôn Hiệp Tuyển — Quyển 1, bản điện tử ghi nguồn ấn bản 1928, bài ngày 8-4-1926','8 Avril 1926','Đoạn nằm dưới đề mục Cao Đài, sau phần Thích Ca Mâu Ni Phật giáng cơ. Đối chiếu bản in và quyền sử dụng.','excerpt:https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-8-4-1926');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) VALUES ('f17f8dc1-e43b-4dd3-a220-000000000003','quote','Ngày 23-4-1926 — Thánh Ngôn Hiệp Tuyển','Đạo phát trễ một ngày là một ngày hại nhơn sanh.','Đức Chí Tôn','https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-23-4-1926','Thánh Ngôn Hiệp Tuyển — Quyển 1, bản điện tử ghi nguồn ấn bản 1928, bài ngày 23-4-1926','22 và 23-4-1926 · 11 và 12-3 Bính Dần','Đã đối chiếu với trang điện tử riêng; cần kiểm tra bản in, văn cảnh và quyền sử dụng.','excerpt:https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-23-4-1926');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) VALUES ('f17f8dc1-e43b-4dd3-a220-000000000004','quote','Ngày 24-4-1926 — Thánh Ngôn Hiệp Tuyển','Ai có đức hạnh lớn thì mới ngồi đặng địa vị của THẦY ban thưởng.','Đức Chí Tôn','https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-24-4-1926','Thánh Ngôn Hiệp Tuyển — Quyển 1, bản điện tử ghi nguồn ấn bản 1928, bài ngày 24-4-1926','24 Avril 1926','Đã đối chiếu với trang điện tử riêng; cần kiểm tra bản in, văn cảnh và quyền sử dụng.','excerpt:https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-24-4-1926');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) VALUES ('f17f8dc1-e43b-4dd3-a220-000000000005','quote','Ngày 30-5-1926 — Thánh Ngôn Hiệp Tuyển','TA nói cho chúng sanh biết rằng: Gặp Tam Kỳ Phổ Độ nầy mà không tu, thì không còn trông mong siêu rỗi.','Đức Chí Tôn','https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-30-5-1926','Thánh Ngôn Hiệp Tuyển — Quyển 1, bản điện tử ghi nguồn ấn bản 1928, bài ngày 30-5-1926','Trường Sanh Tự (Cần Giuộc), 30 Mai 1926 · 19 tháng tư (Bính Dần)','Đã đối chiếu với trang điện tử riêng; cần kiểm tra bản in, văn cảnh và quyền sử dụng.','excerpt:https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-30-5-1926');
