INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,source_url,citation,source_date,note,discovered_key) VALUES ('f17f8dc1-e43b-4dd3-a230-000000000001','history','ĐẠI LỄ KHAI ĐẠO NĂM BÍNH DẦN','Theo bài viết của Hội Thánh, ngày rằm tháng 10 năm Bính Dần (1926) là ngày Khai Đạo Cao Đài.','https://caodai.com.vn/vn/news-detail/ngay-le-khai-dao-nam-thu-88-tai-thanh-that-saigon.html','Hội Thánh Cao Đài Tòa Thánh Tây Ninh – bài hồi cố Đạo sử','15/10/1926 ÂL','Bản tóm lược để Ban Quản trị đối chiếu với sử liệu gốc, xác nhận ngày âm và quyền sử dụng trước khi công bố.','history:https://caodai.com.vn/vn/news-detail/ngay-le-khai-dao-nam-thu-88-tai-thanh-that-saigon.html');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,source_url,citation,source_date,note,discovered_key) VALUES ('f17f8dc1-e43b-4dd3-a230-000000000002','history','ĐỨC CHÍ TÔN BAN TỊCH ĐẠO CHO CHỨC SẮC NAM PHÁI','Bài Thuyết Đạo vía Đức Quan Thánh Đế Quân năm 2011 nhắc lại việc ban Tịch Đạo cho Chức Sắc Nam phái vào Tý thời chuyển sang mồng Hai tháng bảy Bính Dần.','https://caodai.com.vn/vn/news-detail/bai-thuyet-dao-via-duc-quan-thanh-de-quan-dl-24-7-2011.html','Hội Thánh Cao Đài Tòa Thánh Tây Ninh – bài hồi cố Đạo sử','02/07/1926 ÂL','Bản tóm lược để Ban Quản trị đối chiếu với sử liệu gốc, xác nhận ngày âm và quyền sử dụng trước khi công bố.','history:https://caodai.com.vn/vn/news-detail/bai-thuyet-dao-via-duc-quan-thanh-de-quan-dl-24-7-2011.html');
